function solution(str) {
  let strMap = new Map();
  let count = 0;
  let left = 0;
  let startIndex = 0;
  for (let right = 0; right < str.length; right++) {
    const char = str[right];
    if (strMap.has(char) && strMap.get(char) >= left) {
      left = strMap.get(char) + 1;
    }
    strMap.set(char, right);
    if ( right - left + 1 > count) {
      count = right - left + 1;
      startIndex = left;
    }
  }
  const substring = str.slice(startIndex, startIndex + count);
  return [count, substring];
}

function solution(nums, target) {
  const sums = new Map([[0, -1]]);
  let currentSum = 0;
  for (let end = 0; end < nums.length; end++) {
    currentSum += nums[end];
    const targetSum = currentSum - target;
    if (sums.has(targetSum)) {
      const start = sums.get(targetSum) + 1;
      return `(${start}, ${end})`
    }
    if (!sums.has(currentSum)) {
      sums.set(currentSum, end);
    }
  }
  return null;
}

function solution(nums, k) {
  if (k === 1) return 0;
  if (k > nums.length) return -1;
  const m = new Map();
  let l = 0;
  for (let r = 0; r < nums.length; r++) {
    const num = nums[r];
    if (m.has(num) && m.get(num) >= l) {
      l = m.get(num) + 1;
    }
    m.set(num, r);
    if (r - l + 1 === k) return l;
  }
  return -1;
}

