function solution(s, p) {
  if ((p.length > s.length) || p.length === 0) return [];
  if (p === s) return [0];
  const m = new Map();
  const res = [];
  let l = 0;
  let req = p.length;
  for (let c of p) m.set(c, (m.get(c) || 0) + 1);
  for (let r = 0; r < s.length; r++) {
    const rchar = s[r];
    if (m.has(rchar)) {
      if (m.get(rchar) > 0) req--;
      m.set(rchar, m.get(rchar) - 1);
    }
    while (req === 0) {
      const lchar = s[l];
      if (m.has(lchar)) {
        m.set(lchar, m.get(lchar) + 1);
        if (m.get(lchar) > 0) {
          if (r - l + 1 === p.length) res.push(l);
          req++;
        }
      }
      l++;
    }

  }
  return res;
}

function solution(str1, str2) {
  if (str2.length < str1.length) return false;
  const am1 = new Map();
  const k = str1.length;
  let count = str1.length;

  for (let char of str1) {
    am1.set(char, (am1.get(char) || 0) + 1)
  }

  for (let r = 0; r < str2.length; r++) {
    const rchar = str2[r];
    if (am1.has(rchar) && am1.get(rchar) > 0) count--;
    am1.set(rchar, (am1.get(rchar) || 0) - 1)
    if (r >= k) {
      const lchar = str2[r - k];
      if (am1.get(lchar) >= 0) count++;
      am1.set(lchar, am1.get(lchar) + 1)
    }
    if (count === 0) return true;
  }

  return false;
}

function solution(nums, target) {
  let left = 0;
  let right = nums.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    const num = nums[mid];

    if (num === target) return mid;
    num < target ? (left = mid + 1) : (right = mid - 1);
  }

  return left;
}

