  for (let c of t) m.set(c, (m.get(c) || 0) + 1);
  for (let r = 0; r < str.length; r++) {
    const rchar = str[r];

    if (m.has(rchar)) {
      let value = m.get(rchar);
      if (m.get(rchar) > 0) rc--;
      m.set(rchar, value - 1);
