function solution(s, words) {
  if (s.length === 0 || words.length === 0) return [];
  const getChunk = (_s, _e) => s.slice(_s, _e);
  const m = new Map();
  const wl = words[0].length;
  const k = words.length;
  if (s.length < wl * k) return [];
  const res = [];
  for (let w of words) m.set(w, (m.get(w) || 0) + 1);
  for (let i = 0; i < wl; i++) {
    let l = i;
    let req = k;
    for (let r = i; r <= s.length - wl; r += wl) {
      const w = getChunk(r, r + wl);
      if (m.has(w)) {
        if (m.get(w) > 0) req--;
        m.set(w, m.get(w) - 1);
        while (m.get(w) < 0) {
          const _w = getChunk(l, l + wl);
          m.set(_w, m.get(_w) + 1);
          if (m.get(_w) > 0) req++;
          l += wl;
        }
        if (req === 0) res.push(l)
      } else {
        while (l < r) {
          const _w = getChunk(l, l + wl);
          m.set(_w, m.get(_w) + 1);
          l += wl;
        }
        l = r + wl;
        req = k;
      }
    }
    while (l < s.length - wl + 1) {
      const w = getChunk(l, l + wl);
      if (m.has(w)) {
        m.set(w, m.get(w) + 1);
      }
      l += wl;
    }
  }
  return res;
}

function solution(nums, k) {
  if (k > nums.length || k < 1 || nums.length === 0) return 0;
  const s = new Set();
  let maxSum = -Infinity;
  let sum = 0;
  let l = 0;
  for (let r = 0; r < nums.length; r++) {
    const curNum = nums[r];
    while (s.has(curNum)) {
      s.delete(nums[l]);
      sum -= nums[l];
      l++;
    }
    s.add(curNum);
    sum += curNum;
    if (r - l + 1 > k) {
      s.delete(nums[l]);
      sum -= nums[l];
      l++;
    }
    if (r - l + 1 === k) {
      maxSum = Math.max(maxSum, sum);
    }
  }
  return maxSum === -Infinity ? 0 : maxSum;
}

