  if (k >= str.length) return str.length;
  if (k === 0) return 0;
  const m = new Map();
  let max = 0;
  let l = 0;
  m.set(str[0], 1);
  for (let r = 1; r < str.length; r++) {
    const char = str[r];
    m.set(char, (m.get(char) || 0) + 1);

    while (m.size > k) {
      m.set(str[l], m.get(str[l]) - 1);
      if (m.get(str[l]) <= 0) m.delete(str[l]);
      l++;
    }
    max = Math.max(max, r - l + 1);
  }
  return max;
}
